import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Magic status and open questions","description":"","frontmatter":{},"headers":[],"relativePath":"en/game-design/magic/status-and-open-questions.md","filePath":"en/game-design/magic/status-and-open-questions.md"}'),r={name:"en/game-design/magic/status-and-open-questions.md"};function s(o,e,l,d,c,m){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="magic-status-and-open-questions" tabindex="-1">Magic status and open questions <a class="header-anchor" href="#magic-status-and-open-questions" aria-label="Permalink to &quot;Magic status and open questions&quot;">​</a></h1><p><strong>Design status:</strong> Proposed; listed decisions remain Unresolved. Existing Accepted foundations retain their scope. <strong>Implementation:</strong> no Batch 04 gameplay implementation established. <strong>Availability:</strong> not established for this redesign. <strong>Verification:</strong> documentation reconciliation only, not runtime validation. <strong>Reviewed:</strong> 2026-10-09 against Batch 04 and <a href="/Syrolands-Public/en/game-design/magic.html">earlier magic design</a>.</p><p><a href="/Syrolands-Public/en/guide/magic/overview.html">Player guide</a> · <a href="/Syrolands-Public/en/game-design/magic.html">Magic overview</a> · <a href="/Syrolands-Public/en/game-design/magic/status-and-open-questions.html">Status and open questions</a></p><h2 id="status-and-ownership" tabindex="-1">Status and ownership <a class="header-anchor" href="#status-and-ownership" aria-label="Permalink to &quot;Status and ownership&quot;">​</a></h2><p>Batch 04 is Proposed design, not gameplay delivery. Active Memory, Familiarity, combat book reading, scroll reference bypass, redesigned reagents, Inscription variants and modular VFX are not established as implemented or live. Existing accepted server authority, independent anatomy, global Hits versus local integrity and separate Local Trauma keep their scope; the melee experiment is not validation of magic.</p><p>The <a href="/Syrolands-Public/en/game-design/magic.html">overview</a> owns institutions, Magery execution/Mastery, Meditation/Concentration, localized casting, casting components and earlier forbidden-tradition proposals. Linked focused pages own Core Patterns, variants, memory, physical materials, Inscription and visual grammar. Earlier heading URLs remain usable.</p><h2 id="reconciliation-register" tabindex="-1">Reconciliation register <a class="header-anchor" href="#reconciliation-register" aria-label="Permalink to &quot;Reconciliation register&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source / overlap</th><th>Treatment and remaining conflict</th></tr></thead><tbody><tr><td>Earlier magic knowledge, teachers and academies</td><td>Retained. Core Patterns clarify stable identity; discovery remains separate from execution skill</td></tr><tr><td>Mastery versus Familiarity</td><td>Preserve broader discipline/affinity Mastery; per-Core-Pattern practice is a distinct layer outside skillcap. Interaction remains open</td></tr><tr><td>Earlier prepared modifier configurations</td><td>Preserve proposal and extend with Active Memory; a learned/memorized core does not decide every variant&#39;s access</td></tr><tr><td>Scroll teaching and copying</td><td>Ordinary scrolls grant temporary execution, not permanent learning. Batch 04 teaching artifacts require separate explicit policy; do not erase the prior restriction on normal tradable learning scrolls</td></tr><tr><td>Personal book protection</td><td>Preserve permanent knowledge; latest proposal distinguishes personal representation from lootable rare physical books. Exact replacement/retention mechanism stays open; blessing/Sacred status is not selected</td></tr><tr><td>Batch 02 skill bands and learning from zero</td><td>Shared progression remains owner. Magic +5 blocks and 55–60 first-day examples remain illustrative; reliable basics versus difficult advanced spell failure needs balancing, not automatic replacement</td></tr><tr><td>Batch 02 no ordinary 120 / techniques</td><td>Magery 100 is technical mastery; knowledge, schools, modifiers, practice and Inscription extend progression. No cap or roster migration occurs</td></tr><tr><td>Batch 02 INT</td><td>Memory/complexity is a stronger proposed cognitive role; INT–mana relationships and formulas stay unresolved</td></tr><tr><td>Batch 03 pressure, limbs and player execution</td><td>Link to existing Concentration and localized spell profiles. Fatigue, movement, blunt/stun and injury are candidates; no spell inherits melee trauma formulas automatically</td></tr><tr><td>Batch 03 reactive-input conflict</td><td>Physical spellbook play does not resolve or replace the accepted automatic melee baseline; mandatory manual attack remains separately unresolved</td></tr><tr><td>Batch 01 professions</td><td>Inscription uses skill/technique/path, Codex, secrets, teaching, production, commissions and reputation. Alchemy may process reagents; detailed recipes and cross-skill gates stay open</td></tr><tr><td>Equipment and Sacred/Resonant proposals</td><td>Preserve meaningful loss and replaceability. Material reagents/scrolls and valuable physical books carry risk; no broad insurance or sacred-set no-drop rule</td></tr><tr><td>Legacy server/client</td><td>Prior documented inheritance and unreviewed areas are separated in technical evidence boundaries; code presence is not a Batch 04 implementation</td></tr></tbody></table><h2 id="unresolved-decisions" tabindex="-1">Unresolved decisions <a class="header-anchor" href="#unresolved-decisions" aria-label="Permalink to &quot;Unresolved decisions&quot;">​</a></h2><ul><li>Familiarity scale, gain rules, anti-macro/automation limits and relationship to wider Mastery.</li><li>Active Memory capacity formula, INT versus mana, spell complexity cost and memorization preparation time.</li><li>Meditation contribution, Concentration representation/math, recovery and exact reference delays.</li><li>Hotkey-assisted reference without trivializing physical play; page-navigation UX, memory/Familiarity UI disclosure, accessibility and remapping.</li><li>Variant memory rules, major/minor modifier counts and compatibility/stacking restrictions.</li><li>Reagent families/formulas, substitution and consumption on failed/interrupted actions.</li><li>Scroll casting/reference speed and consumption rules; teaching-scroll versus casting-scroll distinction.</li><li>Personal spellbook physical/knowledge persistence boundary, replacement and rare grimoire loot rules.</li><li>Inscription technique roster, copying/teaching permissions, ward/ritual scope and economic abuse.</li><li>Magic/limb formulas, armor/resistance and multi-region budgets; Concentration pressure and component interactions.</li><li>VFX implementation path, ClassicUO rendering/input limits, assets, disclosure, performance and compatibility.</li></ul><p>Earlier <a href="/Syrolands-Public/en/game-design/magic.html#open-questions">magic open questions</a>, including institutions, forbidden traditions and component rules, remain unresolved. This list is not a delivery schedule and selects no numerical balance.</p><h2 id="evidence-limits" tabindex="-1">Evidence limits <a class="header-anchor" href="#evidence-limits" aria-label="Permalink to &quot;Evidence limits&quot;">​</a></h2><p>No game code, runtime settings, assets, dependencies, networking or save schemas change in this batch. Documentation build/link checks establish site consistency, not casting behavior, learning, game feel or balance. No new accepted ADR or implementation authorization is inferred from the supplied source.</p>',13)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
